solution.css:
:root {
  --focus: light-dark(#6d28d9, #c4b5fd);
}
.site-header {
  position: sticky;
  top: 0;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: white;
}
.session-card {
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.session-card:has(a:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: 4px;
}
.session-card a:focus-visible {
  outline: none;
}

html {
  scroll-padding-top: 64px;
}
